  async function rollupCampaignArc(
    deps: PlayDeps,
    db: Db,
    campaignId: string,
  ): Promise<void> {
    const recaps = listSessions(db, { campaignId })
      .map((session) =>
        getSessionRecap(db, { campaignId, sessionId: session.sessionId }),
      )
